import os
from concurrent.futures import ThreadPoolExecutor, as_completed
from bioblend.galaxy import GalaxyInstance
hist='bbd44e69cb8906b500f5fdb3e36f7ae3'
with open(os.environ['GALAXY_API_KEY_FILE']) as f:key=f.read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'],key)
items=[]
for label,cid in [('animals','aecf5328d102def6'),('fungi','f324939bb40e6635')]:
 for e in gi.dataset_collections.show_dataset_collection(cid)['elements']:
  if e['object']['file_ext']"'!='"'newick': items.append((label,e['object']['id']))

def upd(item):
 label,did=item
 gi.histories.update_dataset(hist,did,datatype='newick')
 return label
counts={'animals':0,'fungi':0}; errors=[]
with ThreadPoolExecutor(max_workers=16) as ex:
 for fut in as_completed([ex.submit(upd,x) for x in items]):
  try: counts[fut.result()]+=1
  except Exception as e: errors.append(type(e).__name__+':'+str(e)[:120])
print('updated',counts,'errors',len(errors))
if errors: print(errors[:5])
